/* décor : découpé dans la carte des Ruines d'Alpha de HeartGold/SoulSilver envoyée par Raphaël (voir CREDITS.md) : sable, sentier clair, salles en ruine, rochers */
const AL = { img:null, R:{"bA":[0,0,68,76],"bB":[70,0,72,66],"bC":[144,0,68,80],"bD":[214,0,63,82],"bE":[279,0,68,84],"bF":[349,0,63,82],"boulder":[414,0,11,10],"smash":[427,0,12,12],"tablet":[441,0,14,20]}, K:2.5 }; // K : unités du monde par pixel de la carte
